use std::path::{Path, PathBuf};
use std::{fs, io::Write};
use vibeos_codegen::{generate, generate_all, GENERATORS};

const HELP: &str =
    "Usage: tools/codegen <generator> [--check | --stdout] [--input FILE] [--output FILE]
       tools/codegen --all --check
       tools/codegen --list

Generators: apisets-table, bugcodes, bugcodes-h, error-tables, winerror-consts,
            lcid, ssdt, nls, msvcrt-errlist

--check         Compare generated bytes with output; exit 1 on missing/stale files.
--stdout        Render one output without writing it.
--input FILE    Override the source for a single-source generator.
--output FILE   Override a single output (errlist requires an existing marked file).
--header FILE   Header for winerror-consts; repeat in resolution order.
--root DIR      Checkout whose sources and default outputs to use.

Without --check/--stdout, write changed outputs. All rendering succeeds before writes.
Generated provenance comments retain legacy names for byte compatibility.
";

#[derive(Default)]
struct Args {
    root: Option<PathBuf>,
    name: Option<String>,
    input: Option<PathBuf>,
    output: Option<PathBuf>,
    headers: Vec<PathBuf>,
    check: bool,
    stdout: bool,
    all: bool,
}

fn parse(args: impl IntoIterator<Item = String>) -> Result<Args, String> {
    let mut out = Args::default();
    let mut args = args.into_iter();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--root" => out.root = Some(args.next().ok_or("--root requires a directory")?.into()),
            "--input" => out.input = Some(args.next().ok_or("--input requires a file")?.into()),
            "--output" => out.output = Some(args.next().ok_or("--output requires a file")?.into()),
            "--header" => out
                .headers
                .push(args.next().ok_or("--header requires a file")?.into()),
            "--check" => out.check = true,
            "--stdout" => out.stdout = true,
            "--all" => out.all = true,
            s if !s.starts_with('-') && out.name.is_none() => out.name = Some(arg),
            _ => return Err(format!("unexpected argument: {arg}")),
        }
    }
    if out.all == out.name.is_some() {
        return Err("choose one generator or --all".into());
    }
    if out.check && out.stdout {
        return Err("--check and --stdout are mutually exclusive".into());
    }
    if out.all
        && (out.input.is_some() || out.output.is_some() || !out.headers.is_empty() || out.stdout)
    {
        return Err("--all cannot be combined with input/output overrides or --stdout".into());
    }
    Ok(out)
}

fn write_atomic(path: &Path, text: &str, serial: usize) -> Result<(), String> {
    if path.is_symlink() {
        return Err(format!(
            "refusing to replace output symlink: {}",
            path.display()
        ));
    }
    if fs::read(path).ok().as_deref() == Some(text.as_bytes()) {
        return Ok(());
    }
    let parent = path.parent().ok_or("output has no parent directory")?;
    let temporary = parent.join(format!(
        ".vibeos-codegen-{}-{serial}.tmp",
        std::process::id()
    ));
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temporary)
        .map_err(|e| format!("{}: {e}", temporary.display()))?;
    let result = (|| {
        file.write_all(text.as_bytes())?;
        if let Ok(metadata) = fs::metadata(path) {
            file.set_permissions(metadata.permissions())?;
        }
        file.sync_all()?;
        fs::rename(&temporary, path)
    })();
    if let Err(error) = result {
        let _ = fs::remove_file(&temporary);
        return Err(format!("{}: {error}", path.display()));
    }
    Ok(())
}

fn run(args: Args) -> Result<u8, String> {
    let root = args
        .root
        .unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../.."));
    let outputs = if args.all {
        generate_all(&root)?
    } else {
        generate(
            &root,
            args.name.as_deref().unwrap(),
            args.input.as_deref(),
            args.output.as_deref(),
            &args.headers,
        )?
    };
    if args.stdout {
        if outputs.len() != 1 {
            return Err("--stdout requires a generator with one output".into());
        }
        std::io::stdout()
            .write_all(outputs[0].text.as_bytes())
            .map_err(|e| e.to_string())?;
        return Ok(0);
    }
    let mut stale = false;
    for (i, out) in outputs.iter().enumerate() {
        if args.check {
            if fs::read(&out.path).ok().as_deref() != Some(out.text.as_bytes()) {
                eprintln!("STALE: {}", out.path.display());
                stale = true;
            }
        } else {
            write_atomic(&out.path, &out.text, i)?;
        }
    }
    if !stale {
        eprintln!(
            "OK: {} generated outputs {}",
            outputs.len(),
            if args.check {
                "match"
            } else {
                "written or unchanged"
            }
        );
    }
    Ok(u8::from(stale))
}

fn main() -> std::process::ExitCode {
    let args: Vec<_> = std::env::args().skip(1).collect();
    if args.iter().any(|s| s == "--help" || s == "-h") {
        print!("{HELP}");
        return 0.into();
    }
    if args.iter().any(|s| s == "--list") {
        for name in GENERATORS {
            println!("{name}");
        }
        return 0.into();
    }
    match parse(args).and_then(run) {
        Ok(code) => code.into(),
        Err(error) => {
            eprintln!("vibeos-codegen: {error}");
            2.into()
        }
    }
}
